<script lang="ts">
  import ExportReportDialog from "./ExportReportDialog.svelte";
  import type { ExportResult } from "./export_report";
  let exportReport = $state<ExportResult|null>(null);
  import ContentArtwork from "./ContentArtwork.svelte";
  import GameIcon from "./GameIcon.svelte";
  import { onMount, untrack } from "svelte";
  import ProjectDescription from "./ProjectDescription.svelte";
  import ProviderLogo from "./ProviderLogo.svelte";
  import LoaderLogo from "./LoaderLogo.svelte";
  import UiIcon from "./UiIcon.svelte";
  import ContentProgress from "./ContentProgress.svelte";
  import { contentOperation } from "./content_operations";
  import { invoke } from "@tauri-apps/api/core";
  import {listen} from "@tauri-apps/api/event";
  import { openUrl } from "@tauri-apps/plugin-opener";

  type Pack = { id:string; name:string; game_version:string; loader:string; loader_version:string; version_id:string; icon_data:string; icon_url?:string; created_at:number; install_state?:string; install_error?:string; missing_files?:{filename:string;website_url:string;size:number}[] };
  type Project = { provider:string; id:string; title:string; slug:string; description:string; icon_url:string; preview_url?:string; author:string; downloads:number; categories:string[]; loaders:string[]; url:string; project_type:string; updated:string };
  type Dependency = { id:string; version_id:string; kind:string };
  type ModVersion = { id:string; name:string; number:string; release_type:string; game_versions:string[]; loaders:string[]; size:number; published:string; filename:string; dependencies:Dependency[] };
  type Detail = {project:Project;body:string;gallery:string[];versions:ModVersion[]};
  type InstalledMod = {filename:string;enabled:boolean;size:number;provider:string;project_id:string;name:string;version:string;authors:string[];description:string;icon_data:string;loader:string};
  let { versionCatalog = [], currentVersion = "", currentGameVersion = "", currentLoader = "vanilla", currentPackId = "", username = "Steve", initialSection = "mod", onplay, oninstalled } : {
    versionCatalog:{id:string;kind:string}[];currentVersion:string;currentGameVersion?:string;currentLoader?:string;currentPackId?:string;username:string;
    initialSection?:"mod"|"modpack"|"resourcepack"|"shader";onplay:(versionId:string,instanceId:string)=>void;oninstalled?:()=>void;
  } = $props();

  let section = $state<"mod"|"modpack"|"resourcepack"|"shader"|"studio">("mod");
  let visualContent = $derived(section==="resourcepack"||section==="shader");
  let provider = $state("both");
  let query = $state("");
  let gameVersion = $state("all");
  let loader = $state("all");
  let sort = $state("relevance");
  let category=$state("");
  let categories=$state<{id:string;name:string;provider:string}[]>([]);
  $effect(()=>{const source=provider,kind=section=== "studio"?"mod":section;let alive=true;category="";void invoke<typeof categories>("studio_categories",{provider:source,projectType:kind}).then(rows=>{if(alive)categories=rows;}).catch(()=>{if(alive)categories=[];});return()=>{alive=false;};});
  let projects = $state<Project[]>([]);
  let total = $state(0);
  let page = $state(1);
  let totalPages = $state(1);
  let searching = $state(false);
  let message = $state("");
  let error = $state("");
  let packs = $state<Pack[]>([]);
  let installedVersions = $state<{id:string;game_version:string;loader:string}[]>([]);
  let destination = $state("current");
  let detail = $state<Detail|null>(null);
  let detailVisual = $derived(detail?.project.project_type==="resourcepack"||detail?.project.project_type==="shader");
  let detailLoading = $state(false);
  let detailOpen = $state(false);
  let detailDialog = $state<HTMLDialogElement>();
  let detailError = $state("");
  let detailTab = $state<"description"|"versions"|"dependencies">("description");
  let detailGame = $state("all");
  let detailLoader = $state("all");
  let detailPage = $state(1);
  let dependencyVersion = $state("");
  let dependencyProjects = $state<Record<string,Project>>({});
  let dependencyLookupBusy = $state(false);
  let dependencyLookupError = $state("");
  let installing = $state("");
  let newName = $state("");
  let newGame = $state("");
  let newLoader = $state("fabric");
  let loaderVersions = $state<{version:string;stable:boolean}[]>([]);
  let newLoaderVersion = $state("");
  let loaderLoading = $state(false);
  let loaderError = $state("");
  let iconData = $state("");
  let creating = $state(false);
  let activePack = $state<Pack|null>(null);
  let packMods = $state<InstalledMod[]>([]);
  let packBusy = $state(false);
  let packQuery = $state("");
  let packModsLoading = $state(false);
  let packRequest = 0;
  let searchRequest = 0;
  let libraryRequest=0;
  let detailRequest = 0;
  let loaderRequest = 0;
  const engineChoices = ["vanilla","forge","fabric","neoforge","quilt","optifine"];
  const engineLabel = (engine:string) => ({vanilla:"Vanilla",forge:"Forge",fabric:"Fabric",neoforge:"NeoForge",quilt:"Quilt",optifine:"OptiFine",iris:"Iris",canvas:"Canvas",minecraft:"Minecraft",all:"Todos"})[engine]??engine;
  const number = (n:number) => Intl.NumberFormat("es",{notation:"compact",maximumFractionDigits:1}).format(n);
  const date = (value:string|number) => { const d=new Date(typeof value==="number"?value*1000:value);return Number.isNaN(d.getTime())?"Sin fecha":d.toLocaleDateString("es"); };
  const bytes = (n:number) => n>=1024*1024?`${(n/1024/1024).toFixed(1)} MB`:`${(n/1024).toFixed(0)} KB`;
  let filteredVersions = $derived(detail?.versions.filter(v=>(detailGame==="all"||v.game_versions.includes(detailGame))&&(detailLoader==="all"||v.loaders.includes(detailLoader)))??[]);
  let filePages = $derived(Math.max(1,Math.ceil(filteredVersions.length/12)));
  let detailGames = $derived([...new Set(detail?.versions.flatMap(v=>v.game_versions)??[])].sort((a,b)=>b.localeCompare(a,undefined,{numeric:true})));
  let detailEngines = $derived([...new Set(detail?.versions.flatMap(v=>v.loaders)??[])]);
  let shownDependencies = $derived(detail?.versions.find(v=>v.id===dependencyVersion)?.dependencies??detail?.versions[0]?.dependencies??[]);
  let allGames = $derived([...new Set(versionCatalog.map(v=>v.id))]);
  let filteredPackMods = $derived(packMods.filter(m=>[m.filename,m.name,m.version,...m.authors].join(" ").toLowerCase().includes(packQuery.toLowerCase())));
  $effect(()=>{if(detailOpen&&detailDialog&&!detailDialog.open)detailDialog.showModal();});
  $effect(()=>{if(section==="studio")untrack(()=>{void loadLoaderVersions();});});
  $effect(()=>{
    const source=detail?.project.provider;
    const ids=[...new Set(shownDependencies.map(dependency=>dependency.id).filter(Boolean))].slice(0,50);
    dependencyLookupBusy=false;dependencyLookupError="";
    if(!detailOpen||detailTab!=="dependencies"||!source||!ids.length)return;
    let cancelled=false;dependencyLookupBusy=true;dependencyLookupError="";
    void invoke<Project[]>("studio_dependency_projects",{provider:source,projectIds:ids}).then(results=>{
      if(cancelled)return;const resolved={...dependencyProjects};for(const project of results)resolved[`${source}:${project.id}`]=project;dependencyProjects=resolved;
      if(results.length<ids.length)dependencyLookupError="Algunos nombres no están disponibles; se conserva su identificador para consultarlos.";
    }).catch(reason=>{if(!cancelled)dependencyLookupError=`No se pudieron cargar los nombres: ${String(reason)}`;}).finally(()=>{if(!cancelled)dependencyLookupBusy=false;});
    return()=>{cancelled=true;};
  });

  onMount(()=>{
    let alive=true,stopArt:(()=>void)|undefined;
    void listen<{pack_id:string;filename:string;icon_data:string}>("studio-mod-art",event=>{const art=event.payload;if(alive&&activePack?.id===art.pack_id)packMods=packMods.map(mod=>mod.filename===art.filename&&!mod.icon_data?{...mod,icon_data:art.icon_data}:mod);}).then(stop=>{if(alive)stopArt=stop;else stop();});
    section=initialSection;
    if(initialSection==="resourcepack"||initialSection==="shader")gameVersion=currentGameVersion||"all";
    newGame=currentGameVersion||versionCatalog.find(v=>v.id===currentVersion)?.id||versionCatalog.find(v=>v.kind==="release")?.id||"1.21.1";
    if(currentLoader!=="vanilla"&&engineChoices.includes(currentLoader))newLoader=currentLoader;
    if(currentPackId)destination=currentPackId;
    void refreshPacks();
    void search();
    return()=>{alive=false;stopArt?.();};
  });
  function pageButtons(current:number,max:number):number[]{
    if(max<=7)return Array.from({length:max},(_,i)=>i+1);
    return [...new Set([1,...Array.from({length:5},(_,i)=>current+i-2).filter(n=>n>1&&n<max),max])].sort((a,b)=>a-b);
  }
  async function search(reset=false){
    if(reset)page=1;const request=++searchRequest;searching=true;error="";
    try{
      const result=await invoke<{projects:Project[];total_hits:number;page:number;total_pages:number;warnings:string[]}>("studio_search",{provider,query,projectType:section==="studio"?"mod":section,gameVersion,loader:visualContent?"all":loader,sort,page,category:category||null});
      if(request!==searchRequest)return;projects=result.projects;total=result.total_hits;totalPages=result.total_pages;


      for(const line of result.warnings??[])void invoke("record_launcher_log",{stream:"catalogo",line}).catch(()=>{});
    }catch(e){if(request===searchRequest){error=String(e);projects=[];total=0;}}
    finally{if(request===searchRequest)searching=false;}
  }
  function changeSection(next:"mod"|"modpack"|"resourcepack"|"shader"|"studio") { section=next;category="";query="";message="";error="";loader="all";if(next!=="studio")void search(true); }
  async function openContentFolder(){
    try {
      const selected=destination.startsWith("version:")?destination.slice(8):currentVersion;
      await invoke("open_player_folder",{username,versionId:selected,instanceId:destination!=="current"&&!destination.startsWith("version:")?destination:null,folder:section==="shader"?"shaderpacks":"resourcepacks"});
    }catch(e){error=String(e);}
  }
  async function refreshPacks(){
    const request=++libraryRequest;
    const results=await Promise.allSettled([invoke<Pack[]>("studio_list_packs"),invoke<typeof installedVersions>("list_installed_versions")]);
    if(request!==libraryRequest)return;
    if(results[0].status==="fulfilled"){packs=results[0].value;if(packs.some(p=>!p.icon_data))void invoke<Pack[]>("studio_enrich_library_art").then(rows=>{if(request!==libraryRequest)return;packs=packs.map(pack=>{const art=rows.find(row=>row.id===pack.id);return art&&!pack.icon_data?{...pack,icon_data:art.icon_data,icon_url:art.icon_url}:pack;});}).catch(()=>{});}else error=String(results[0].reason);
    if(results[1].status==="fulfilled")installedVersions=results[1].value;
    oninstalled?.();
  }
  async function openProject(project:Project){
    const request=++detailRequest;detailOpen=true;detailLoading=true;detail=null;detailError="";detailTab="description";detailGame=project.project_type==="shader"||project.project_type==="resourcepack"?gameVersion:"all";detailLoader="all";detailPage=1;
    try{const result=await invoke<Detail>("studio_project",{provider:project.provider,projectId:project.id});if(request===detailRequest){detail=result;dependencyVersion=result.versions[0]?.id??"";}}
    catch(e){if(request===detailRequest)detailError=String(e);}finally{if(request===detailRequest)detailLoading=false;}
  }
  function closeDetail(){detailDialog?.close();detailOpen=false;detailRequest++;detailLoading=false;}
  async function installVersion(version:ModVersion){
    if(!detail)return;installing=version.id;detailError="";message="";
    try{
      const versionId=destination.startsWith("version:")?destination.slice(8):currentVersion.split(/\s+/)[0];
      message=await invoke<string>("studio_install_version",{provider:detail.project.provider,projectId:detail.project.id,fileId:version.id,projectType:detail.project.project_type,packId:destination!=="current"&&!destination.startsWith("version:")?destination:null,username,versionId});
      await refreshPacks();if(activePack)await selectPack(activePack,false);oninstalled?.();
    }catch(e){detailError=String(e);await refreshPacks();if(detail?.project.project_type==="modpack"&&String(e).includes("La instancia quedó pendiente.")){const pending=packs.find(pack=>pack.install_state&&pack.install_state!=="ready");if(pending){closeDetail();section="studio";await selectPack(pending);}}}finally{installing="";}
  }
  async function loadLoaderVersions(){
    if(!newGame)return;const request=++loaderRequest;loaderLoading=true;loaderError="";loaderVersions=[];newLoaderVersion="";
    try{const versions=await invoke<typeof loaderVersions>("studio_loader_versions",{loader:newLoader,gameVersion:newGame});if(request===loaderRequest){loaderVersions=versions;newLoaderVersion=versions.find(v=>v.stable)?.version??versions[0]?.version??"";}}
    catch(e){if(request===loaderRequest)loaderError=String(e);}finally{if(request===loaderRequest)loaderLoading=false;}
  }
  function readFile(file:File):Promise<string>{return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file);});}
  async function changeIcon(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;if(file.size>8*1024*1024){error="El icono supera 8 MB.";return;}try{iconData=await readFile(file);}catch(e){error=String(e);}}
  async function createPack(){
    creating=true;error="";message="Instalando el motor y preparando la instancia aislada…";
    try{const pack=await invoke<Pack>("studio_create_pack",{name:newName,gameVersion:newGame,loader:newLoader,loaderVersion:newLoaderVersion,iconBase64:iconData||null});await refreshPacks();await selectPack(pack);newName="";iconData="";message=`${pack.name} está listo. Puedes añadir mods o iniciar la instancia.`;}
    catch(e){error=String(e);message="";}finally{creating=false;}
  }
  async function selectPack(pack:Pack,reset=true){const request=++packRequest;activePack=pack;if(reset)packQuery="";packMods=[];packModsLoading=true;try{const mods=await invoke<InstalledMod[]>("studio_list_pack_mods",{packId:pack.id});if(request===packRequest){packMods=mods;if(mods.some(m=>!m.icon_data))void invoke<InstalledMod[]>("studio_enrich_mod_art",{packId:pack.id}).then(rows=>{if(request===packRequest)packMods=packMods.map(mod=>({...mod,icon_data:rows.find(row=>row.filename===mod.filename)?.icon_data||mod.icon_data}));}).catch(()=>{});}}catch(e){if(request===packRequest)error=String(e);}finally{if(request===packRequest)packModsLoading=false;}}
  async function toggleMod(mod:InstalledMod){if(!activePack)return;try{await invoke("studio_set_pack_mod_enabled",{packId:activePack.id,fileName:mod.filename,enabled:!mod.enabled});await selectPack(activePack,false);}catch(e){error=String(e);}}
  async function removeMod(mod:InstalledMod){if(!activePack)return;try{await invoke("studio_remove_pack_mod",{packId:activePack.id,fileName:mod.filename});await selectPack(activePack,false);message=`Se quitó ${mod.name||mod.filename} de la instancia.`;}catch(e){error=String(e);}}
  function addPackMods(){if(!activePack)return;destination=activePack.id;gameVersion=activePack.game_version;loader=activePack.loader;changeSection("mod");}
  async function exportPack(format:string){if(!activePack)return;packBusy=true;error="";try{const report=await invoke<ExportResult>("studio_export_pack",{packId:activePack.id,format});exportReport=report;message=`Pack exportado: ${report.path}`;}catch(e){error=String(e);}finally{packBusy=false;}}
  async function importPack(event:Event){
    const input=event.currentTarget as HTMLInputElement;const file=input.files?.[0];if(!file)return;
    if(file.size>512*1024*1024){error="El archivo supera el límite de importación de 512 MB.";input.value="";return;}
    packBusy=true;error="";message="Validando el pack, instalando el motor y descargando sus archivos…";
    try{const archiveBase64=await readFile(file);const pack=await invoke<Pack>("studio_import_pack",{archiveBase64,fileName:file.name});await refreshPacks();await selectPack(pack);section="studio";message=`${pack.name} importado como instancia aislada.`;}catch(e){error=String(e);message="";await refreshPacks();}finally{packBusy=false;input.value="";}
  }
  async function retryPack(){
    if(!activePack)return;packBusy=true;error="";
    try{const pack=await invoke<Pack>("studio_retry_pack",{packId:activePack.id});await refreshPacks();await selectPack(pack);message=`${pack.name} se instaló correctamente.`;}
    catch(e){error=String(e);await refreshPacks();if(activePack){const updated=packs.find(p=>p.id===activePack?.id);if(updated)activePack=updated;}}
    finally{packBusy=false;}
  }
  async function supplyFiles(event:Event){
    const input=event.currentTarget as HTMLInputElement,files=[...input.files??[]];if(!activePack||!files.length)return;
    packBusy=true;error="";let remaining=1;
    try{
      for(const file of files){if(file.size>512*1024*1024)throw new Error("El archivo supera 512 MB");remaining=await invoke<number>("studio_supply_pack_file",{packId:activePack.id,fileName:file.name,fileBase64:await readFile(file)});}
      await refreshPacks();const updated=packs.find(p=>p.id===activePack?.id);if(updated)activePack=updated;
      message="Archivos comprobados correctamente.";
      if(remaining===0)await retryPack();
    }catch(e){error=String(e);await refreshPacks();const updated=packs.find(p=>p.id===activePack?.id);if(updated)activePack=updated;}finally{packBusy=false;input.value="";}
  }
  function openExternal(url:string){if(/^https:\/\//i.test(url))void openUrl(url).catch(e=>error=String(e));}
</script>

<ExportReportDialog report={exportReport} onclose={()=>exportReport=null}/>
<div class="mod-studio">
  <header class="studio-heading"><div><span class="eyebrow">TP LAUNCHER · CONTENT STUDIO</span><h2>Tu próxima forma de jugar.</h2><p>Descubre mods, shaders y paquetes de recursos. Personaliza cada instalación a tu manera.</p></div></header>
  <nav class="studio-tabs" aria-label="Estudio de contenido"><button class:active={section==="mod"} onclick={()=>changeSection("mod")}><GameIcon name="crafting_table" size={18}/>Explorar mods</button><button class:active={section==="modpack"} onclick={()=>changeSection("modpack")}><GameIcon name="chest" size={18}/>Descubrir modpacks</button><button class:active={section==="shader"} onclick={()=>changeSection("shader")}><GameIcon name="ender_eye" size={18}/>Explorar shaders</button><button class:active={section==="resourcepack"} onclick={()=>changeSection("resourcepack")}><GameIcon name="painting" size={18}/>Paquetes de recursos</button><button class:active={section==="studio"} onclick={()=>changeSection("studio")}><GameIcon name="book" size={18}/>Mis modpacks <span>{packs.length}</span></button></nav>
  {#if $contentOperation}<ContentProgress />{/if}
  {#if message}<p class="notice success" role="status">{message}</p>{/if}
  {#if error}<p class="notice error" role="alert">{error}</p>{/if}

  {#if section!=="studio"}
    <section class="search-surface">
      <div class="search-top"><div class="segmented" aria-label="Proveedor de contenido">{#each [["modrinth","Modrinth"],["curseforge","CurseForge"],["both","Ambos · unificado"]] as source}<button class:active={provider===source[0]} onclick={()=>{provider=source[0];category="";void search(true);}}>{#if source[0]==="both"}<span class="unified-logos"><ProviderLogo provider="modrinth" size={17}/><ProviderLogo provider="curseforge" size={17}/></span>{:else}<ProviderLogo provider={source[0]} size={19}/>{/if}{source[1]}</button>{/each}</div><span class="result-meta">{number(total)} proyectos disponibles</span></div>
      <label class="category-filter">Categoría<select bind:value={category} onchange={()=>void search(true)}><option value="">Todas las categorías</option>{#each categories as c}<option value={c.id}>{c.name} · {c.provider==='modrinth'?'Modrinth':'CurseForge'}</option>{/each}</select><small>Clasificación del proveedor. Al elegir una categoría, la búsqueda consulta esa plataforma.</small></label>
      <form class="search-controls" onsubmit={(event)=>{event.preventDefault();void search(true);}}><label class="search-input"><UiIcon name="search" size={19}/><input aria-label="Buscar contenido" placeholder={section==="shader"?"Busca iluminación, sombras y nuevos paisajes…":section==="resourcepack"?"Busca texturas, sonidos y nuevos estilos…":section==="mod"?"Busca ese mod que cambia tu mundo…":"Encuentra tu próxima aventura…"} bind:value={query}/></label><button class="accent" disabled={searching}><UiIcon name={searching?"refresh":"search"} size={16}/>{searching?"Buscando…":"Buscar"}</button></form>
      <div class="filter-grid" class:visual-filters={visualContent}><label>Minecraft<select bind:value={gameVersion} onchange={()=>void search(true)}><option value="all">Todas las versiones</option>{#each allGames as game}<option value={game}>{game}</option>{/each}</select></label>{#if !visualContent}<label>Motor<select bind:value={loader} onchange={()=>void search(true)}><option value="all">Todos los motores</option>{#each engineChoices.filter(l=>l!=="optifine") as engine}<option value={engine}>{engineLabel(engine)}</option>{/each}</select></label>{/if}<label>Ordenar por<select bind:value={sort} onchange={()=>void search(true)}><option value="relevance">Relevancia</option><option value="downloads">Más descargados</option><option value="recent">Actualizados recientemente</option></select></label><label>Destino de instalación<select bind:value={destination}><option value="current">Instalación actual · {currentVersion}</option><optgroup label="Mis modpacks">{#each packs as pack}<option value={pack.id}>{pack.name} · {pack.game_version} / {engineLabel(pack.loader)}</option>{/each}</optgroup><optgroup label="Instalaciones del launcher">{#each installedVersions.filter(v=>visualContent||v.loader!=="vanilla") as installed}<option value={`version:${installed.id}`}>{installed.id}</option>{/each}</optgroup></select></label></div>
    </section>
    {#if visualContent}<div class="visual-content-note"><div><UiIcon name={section==="shader"?"image":"cube"} size={23}/><span><strong>{section==="shader"?"Otra luz para tus mundos":"Dale un nuevo estilo a Minecraft"}</strong><small>{section==="shader"?"Los archivos se guardan en shaderpacks. Necesitas Iris u OptiFine compatible para activarlos en el juego.":"Los archivos se guardan en resourcepacks. Actívalos desde Opciones → Paquetes de recursos en Minecraft."}</small></span></div><button onclick={()=>void openContentFolder()}><UiIcon name="folder" size={16}/>Abrir carpeta de destino</button></div>{/if}
    <div class="catalog-summary"><h3>{section==="shader"?"Iluminación que transforma tus aventuras":section==="resourcepack"?"Texturas y sonidos para tu mundo":section==="mod"?"Amplía tu mundo":"Mundos listos para descubrir"}</h3><small>{searching?"Consultando proveedores oficiales…":`Página ${page} de ${totalPages}`}</small></div>
    {#if searching}<div class="project-grid skeleton-grid" aria-label="Cargando proyectos">{#each Array(6) as _}<div class="skeleton-card"><div></div><span></span><span></span></div>{/each}</div>{:else if projects.length}
      <div class="project-grid">{#each projects as project (`${project.provider}:${project.id}`)}<button class="project-card" class:visual-card={visualContent} onclick={()=>void openProject(project)}>{#if visualContent}<div class="project-cover">{#if project.preview_url||project.icon_url}<img src={project.preview_url||project.icon_url} alt={`Vista previa de ${project.title}`} loading="lazy" onerror={(event)=>{const image=event.currentTarget as HTMLImageElement;if(project.icon_url&&image.getAttribute('src')!==project.icon_url){image.src=project.icon_url;}else{image.style.visibility='hidden';}}}/>{:else}<UiIcon name="image" size={44}/>{/if}<span>{section==="shader"?"SHADERPACK":"RESOURCEPACK"}</span></div>{/if}<div class="project-top">{#if project.icon_url}<img src={project.icon_url} alt="" loading="lazy"/>{:else}<div class="project-placeholder"><UiIcon name="cube" size={28}/></div>{/if}<span class="provider-badge" class:curseforge={project.provider==="curseforge"}><ProviderLogo provider={project.provider} size={23}/></span></div><h4>{project.title}</h4><small class="author">por {project.author||"el equipo del proyecto"}</small><p>{project.description}</p><div class="tag-row">{#each project.categories.slice(0,3) as category}<span>{category}</span>{/each}</div><footer><span><UiIcon name="download" size={12}/>{number(project.downloads)}</span><strong>Ver proyecto <UiIcon name="external" size={13}/></strong></footer></button>{/each}</div>
    {:else}<div class="empty-state"><span class="empty-mark"><UiIcon name="search" size={34}/></span><h3>{error?"El catálogo no está disponible":"No hay resultados para estos filtros"}</h3><p>{error?"Revisa la conexión o cambia de proveedor y vuelve a buscar.":"Prueba otra versión de Minecraft, motor o término de búsqueda."}</p><button onclick={()=>{query="";gameVersion="all";loader="all";void search(true);}}><UiIcon name="refresh" size={15}/>Restablecer filtros</button></div>{/if}
    <nav class="pagination" aria-label="Páginas del catálogo"><button disabled={page<=1||searching} onclick={()=>{page--;void search();}}><UiIcon name="left" size={15}/>Anterior</button>{#each pageButtons(page,totalPages) as p}<button class:active={page===p} disabled={searching} onclick={()=>{page=p;void search();}} aria-current={page===p?"page":undefined}>{p}</button>{/each}<button disabled={page>=totalPages||searching} onclick={()=>{page++;void search();}}>Siguiente<UiIcon name="arrow" size={15}/></button></nav>
  {:else}
    <div class="pack-workspace"><section class="create-pack surface"><span class="eyebrow">CREA ALGO TUYO</span><h3><GameIcon name="crafting_table" size={20}/>Nuevo modpack</h3><p>Diseña una experiencia propia. Elige el motor y organiza mods, mundos y ajustes en una instancia dedicada.</p><label>Nombre del modpack<input placeholder="Mi aventura survival" bind:value={newName} maxlength="80"/></label><div class="icon-picker">{#if iconData}<img src={iconData} alt="Icono del nuevo modpack"/>{:else}<div class="icon-empty"><LoaderLogo loader={newLoader} size={34}/></div>{/if}<label class="file-button"><UiIcon name="image" size={16}/>Elegir icono<input type="file" accept="image/png,image/jpeg" onchange={changeIcon}/></label><small>Se ajusta a 128 × 128 px</small></div><label>Versión de Minecraft<select bind:value={newGame} onchange={()=>void loadLoaderVersions()}>{#if !allGames.includes(newGame)}<option value={newGame}>{newGame}</option>{/if}{#each versionCatalog.filter(v=>v.kind==="release"||v.kind==="snapshot") as game}<option value={game.id}>{game.id}{game.kind==="snapshot"?" · Snapshot":""}</option>{/each}</select></label><fieldset><legend>Motor de la instancia</legend><div class="engine-grid">{#each engineChoices as engine}<button class:active={newLoader===engine} onclick={()=>{newLoader=engine;void loadLoaderVersions();}}><LoaderLogo loader={engine} size={22}/>{engineLabel(engine)}</button>{/each}</div></fieldset><label>Versión del motor<select bind:value={newLoaderVersion} disabled={loaderLoading}><option value="">{loaderLoading?"Consultando catálogo oficial…":loaderVersions.length?"Selecciona una versión":"Sin builds compatibles"}</option>{#each loaderVersions as version}<option value={version.version}>{version.version}{version.stable?" · Estable":" · Experimental"}</option>{/each}</select></label>{#if loaderError}<p class="notice error" role="alert">{loaderError}</p>{/if}<button class="accent create-button" onclick={createPack} disabled={creating||!newName.trim()||!newLoaderVersion}><UiIcon name={creating?"refresh":"plus"} size={16}/>{creating?"Preparando instancia…":"Crear modpack"}</button><label class="file-button import-pack"><UiIcon name="zip" size={16}/>{packBusy?"Importando…":"Importar ZIP / .mrpack"}<input type="file" accept=".zip,.mrpack" onchange={importPack} disabled={packBusy}/></label></section>
    <section class="pack-library"><div class="catalog-summary"><div><h3><GameIcon name="chest" size={20}/>Mi biblioteca</h3><small>{packs.length} instancias independientes</small></div><button onclick={()=>void refreshPacks()}><UiIcon name="refresh" size={15}/>Actualizar</button></div>{#if packs.length}<div class="pack-grid">{#each packs as pack}<button class="pack-card" class:selected={activePack?.id===pack.id} onclick={()=>void selectPack(pack)}><ContentArtwork src={pack.icon_data} alternate={pack.icon_url} name={pack.name} kind="pack" size={48}/><div><h4>{pack.name}</h4><span>Minecraft {pack.game_version}</span><small class="pack-engine"><LoaderLogo loader={pack.loader} size={16}/>{engineLabel(pack.loader)} · {date(pack.created_at)}</small></div>{#if pack.install_state && pack.install_state!=="ready"}<span class="pending-pack">Pendiente</span>{/if}<span class="pack-arrow">›</span></button>{/each}</div>{:else}<div class="empty-state"><span class="empty-mark"><GameIcon name="chest" size={36}/></span><h3>Tu primer pack empieza aquí</h3><p>Elige una versión y un motor en el formulario, o importa un pack compartido.</p></div>{/if}
      {#if activePack}<section class="pack-manager surface"><div class="manager-header"><div><span class="eyebrow">INSTANCIA AISLADA</span><h3>{activePack.name}</h3><p>{activePack.game_version} · {engineLabel(activePack.loader)} {activePack.loader_version}</p></div>{#if activePack.install_state && activePack.install_state!=="ready"}<button class="accent" disabled={packBusy||$contentOperation?.status==="running"} onclick={retryPack}><UiIcon name="refresh" size={16}/>Reintentar instalación</button>{:else}<button class="accent" onclick={()=>activePack&&onplay(activePack.version_id,activePack.id)}><UiIcon name="play" size={17}/>Jugar pack</button>{/if}</div>{#if activePack.install_state && activePack.install_state!=="ready"}<p class="notice error" role="alert">Instalación pendiente. {activePack.install_error}</p>{/if}{#if activePack.missing_files?.length}<section class="manual-files"><h4>Archivos pendientes del autor</h4><p>Descarga estas versiones exactas desde CurseForge. Al importarlas, el launcher verifica su integridad y termina la instalación.</p>{#each activePack.missing_files as file}<div><span data-no-translate>{file.filename}<small>{bytes(file.size)}</small></span><button onclick={()=>openExternal(file.website_url)}><UiIcon name="external" size={15}/>Descarga oficial</button></div>{/each}<label class="file-button"><UiIcon name="download" size={16}/>Importar archivos descargados<input type="file" accept=".jar,.zip" multiple disabled={packBusy} onchange={supplyFiles}/></label></section>{/if}<div class="manager-actions"><button onclick={addPackMods}><UiIcon name="plus" size={15}/>Añadir más mods</button><button onclick={()=>activePack&&invoke("studio_open_pack_folder",{packId:activePack.id}).catch(e=>error=String(e))}><UiIcon name="folder" size={15}/>Abrir carpeta</button><button disabled={packBusy} onclick={()=>void exportPack("zip")}><UiIcon name="zip" size={15}/>Exportar ZIP</button><button disabled={packBusy} onclick={()=>void exportPack("mrpack")}><ProviderLogo provider="modrinth" size={16}/>Exportar .mrpack</button><button onclick={()=>invoke("open_modpack_exports_folder").catch(e=>error=String(e))}><UiIcon name="folder" size={15}/>Ver exportaciones</button></div><div class="mod-list-heading"><strong>{packMods.filter(m=>m.enabled).length} activos · {packMods.length} archivos</strong><input aria-label="Filtrar mods instalados" placeholder="Buscar nombre, autor o versión…" bind:value={packQuery}/></div><div class="pack-mod-list">{#if packModsLoading}<p class="muted" role="status">Leyendo los metadatos de tus mods…</p>{:else}{#each filteredPackMods as mod}<article class="mod-file" class:disabled-mod={!mod.enabled}>
        <ContentArtwork src={mod.icon_data} name={mod.name||mod.filename} size={42}/>
        <div class="mod-copy"><strong title={mod.filename}>{mod.name||mod.filename.replace(/\.disabled$/i,"")}</strong><div class="mod-badges">{#if mod.version}<span title="Versión del mod">{mod.version}</span>{/if}{#if mod.authors.length}<span class="mod-author" title={mod.authors.join(", ")}>por {mod.authors.join(", ")}</span>{/if}{#if mod.loader}<LoaderLogo loader={mod.loader} size={15}/>{/if}{#if mod.provider}<ProviderLogo provider={mod.provider} size={15}/>{/if}</div>{#if mod.description}<p class="mod-description" title={mod.description}>{mod.description}</p>{/if}</div>
        <span class="mod-size">{bytes(mod.size)}</span><button class="switch" class:on={mod.enabled} role="switch" aria-checked={mod.enabled} aria-label={`${mod.enabled?"Desactivar":"Activar"} ${mod.name||mod.filename}`} onclick={()=>void toggleMod(mod)}><span></span></button><button class="delete-mod" onclick={()=>void removeMod(mod)} aria-label={`Eliminar ${mod.name||mod.filename}`} title="Eliminar mod"><UiIcon name="trash" size={17}/></button>
        </article>{:else}<p class="muted">{packQuery?"No hay mods que coincidan con la búsqueda.":"Tu instancia está preparada. Añade mods desde el catálogo para crear tu experiencia."}</p>{/each}{/if}</div></section>{/if}
    </section></div>
  {/if}
</div>

{#if detailOpen}
  <dialog bind:this={detailDialog} class="project-detail" aria-modal="true" oncancel={closeDetail} aria-label={detail?.project.title??"Detalle del proyecto"} tabindex="-1" onkeydown={event=>{if(event.key==="Escape")closeDetail();}}><button class="modal-close" aria-label="Cerrar" onclick={closeDetail}><UiIcon name="close" size={20}/></button>
    {#if detailLoading}<div class="detail-loading"><div class="loading-ring"></div><h3>Cargando proyecto y todas sus versiones…</h3><p>Consultando la información publicada por su autor.</p></div>{:else if detail}
      <header class="detail-header">{#if detail.project.icon_url}<img src={detail.project.icon_url} alt=""/>{:else}<div class="project-placeholder"><UiIcon name="cube" size={38}/></div>{/if}<div><span class="provider-badge"><ProviderLogo provider={detail.project.provider} size={24}/></span><h2>{detail.project.title}</h2><p>por {detail.project.author||"el equipo del proyecto"} · {number(detail.project.downloads)} descargas</p><div class="tag-row">{#each [...detail.project.loaders,...detail.project.categories].slice(0,8) as tag}<span>{tag}</span>{/each}</div></div><button class="external-link" onclick={()=>detail&&openExternal(detail.project.url)}><UiIcon name="external" size={15}/>Sitio oficial</button>{#if detailVisual}<button class="accent" onclick={()=>detailTab="versions"}><UiIcon name="download" size={16}/>Ver archivos para instalar</button>{/if}</header>
      <nav class="detail-tabs" aria-label="Información del proyecto"><button class:active={detailTab==="description"} onclick={()=>detailTab="description"}><UiIcon name="image" size={16}/>Descripción y galería</button><button class:active={detailTab==="versions"} onclick={()=>detailTab="versions"}><UiIcon name="grid" size={16}/>Versiones disponibles <span>{detail.versions.length}</span></button><button class:active={detailTab==="dependencies"} onclick={()=>detailTab="dependencies"}><UiIcon name="link" size={16}/>Dependencias</button></nav>
      {#if $contentOperation}<ContentProgress />{/if}
      {#if message}<p class="notice success">{message}</p>{/if}{#if detailError}<p class="notice error" role="alert">{detailError}</p>{/if}
      {#if detailTab==="description"}<div class="detail-description"><p class="project-summary">{detail.project.description}</p><div class="gallery">{#each detail.gallery as url}<button onclick={()=>openExternal(url)} aria-label="Abrir imagen de la galería"><img src={url} alt={`Galería de ${detail.project.title}`} loading="lazy"/></button>{/each}</div><div class="description-body"><ProjectDescription source={detail.body||detail.project.description} /></div></div>
      {:else if detailTab==="versions"}<div class="detail-version-filters"><label>Minecraft<select bind:value={detailGame} onchange={()=>detailPage=1}><option value="all">Todas las versiones</option>{#each detailGames as game}<option value={game}>{game}</option>{/each}</select></label><label>Motor<select bind:value={detailLoader} onchange={()=>detailPage=1}><option value="all">Todos</option>{#each detailEngines as engine}<option value={engine}>{engineLabel(engine)}</option>{/each}</select></label>{#if detail.project.project_type!=="modpack"}<label>Instalar en<select bind:value={destination}><option value="current">Actual · {currentVersion}</option>{#each packs as pack}<option value={pack.id}>{pack.name} · {pack.game_version} / {pack.loader}</option>{/each}{#each installedVersions.filter(v=>detailVisual||v.loader!=="vanilla") as installed}<option value={`version:${installed.id}`}>{installed.id}</option>{/each}</select></label>{:else}<p class="muted">Cada modpack crea una instancia propia con su motor y archivos.</p>{/if}</div><div class="version-table-wrap"><table><thead><tr><th>Versión / archivo</th><th>Tipo</th><th>Compatibilidad</th><th>Archivo</th><th></th></tr></thead><tbody>{#each filteredVersions.slice((detailPage-1)*12,detailPage*12) as version}<tr><td><strong>{version.name||version.number}</strong><small>{version.number} · {version.filename}</small></td><td><span class={`release-badge ${version.release_type}`}>{version.release_type}</span></td><td><div class="version-tags">{#each version.game_versions.slice(0,5) as game}<span>{game}</span>{/each}{#if version.game_versions.length>5}<span title={version.game_versions.join(", ")}>+{version.game_versions.length-5}</span>{/if}</div><small class="version-loaders">{#each version.loaders as engine}<LoaderLogo loader={engine} size={17}/><span>{engineLabel(engine)}</span>{/each}</small></td><td>{bytes(version.size)}<small>{date(version.published)}</small></td><td><button class="accent install-file" disabled={!!installing} onclick={()=>void installVersion(version)}><UiIcon name={installing===version.id?"refresh":"download"} size={15}/>{installing===version.id?"Instalando…":"Instalar esta versión"}</button></td></tr>{:else}<tr><td colspan="5" class="muted">No hay archivos con estos filtros.</td></tr>{/each}</tbody></table></div><nav class="pagination" aria-label="Páginas de archivos"><button disabled={detailPage<=1} onclick={()=>detailPage--}><UiIcon name="left" size={15}/>Anterior</button>{#each pageButtons(detailPage,filePages) as p}<button class:active={detailPage===p} onclick={()=>detailPage=p}>{p}</button>{/each}<button disabled={detailPage>=filePages} onclick={()=>detailPage++}>Siguiente<UiIcon name="arrow" size={15}/></button><small>{filteredVersions.length} archivos coinciden</small></nav>
      {:else}<section class="dependency-panel"><h3>Dependencias por versión</h3><p>Las dependencias obligatorias se resuelven e instalan automáticamente con el archivo elegido.</p><select aria-label="Versión para consultar dependencias" bind:value={dependencyVersion}>{#each detail.versions as version}<option value={version.id}>{version.name||version.number}</option>{/each}</select>{#if dependencyLookupBusy}<p class="muted">Consultando los nombres de las librerías…</p>{/if}{#if dependencyLookupError}<p class="provider-warning">{dependencyLookupError}</p>{/if}<div class="dependency-list">{#each shownDependencies as dependency}{@const library = dependencyProjects[`${detail.project.provider}:${dependency.id}`]}<article>{#if library?.icon_url}<img class="dependency-icon" src={library.icon_url} alt="" loading="lazy" />{/if}<span class:required={dependency.kind==="required"} class="dependency-type">{dependency.kind==="required"?"Obligatoria":dependency.kind==="optional"?"Opcional":dependency.kind==="incompatible"?"Incompatible":"Incluida"}</span><div><strong>{library?.title||(dependency.id?`Proyecto ${dependency.id}`:`Archivo ${dependency.version_id}`)}</strong>{#if dependency.version_id}<small>Archivo exacto: {dependency.version_id}</small>{/if}</div>{#if dependency.id}<button onclick={()=>detail&&void openProject({...detail.project,id:dependency.id})}><UiIcon name="external" size={15}/>Ver proyecto</button>{/if}</article>{:else}<div class="empty-state"><h3>Sin dependencias publicadas</h3><p>Este archivo no declara librerías adicionales.</p></div>{/each}</div></section>{/if}
    {:else}<div class="detail-loading"><h3>No se pudo abrir el proyecto</h3><p class="notice error">{detailError}</p><button onclick={closeDetail}><UiIcon name="left" size={15}/>Volver al catálogo</button></div>{/if}
  </dialog>
{/if}

<style>
.category-filter{display:grid;gap:6px;margin:14px 0;font-size:12px}.category-filter select{padding:10px;background:#101322;color:inherit;border:1px solid #ffffff25;color-scheme:dark}.category-filter small{color:#a89ab4;font-size:10px}

  .manual-files{border:1px solid #d9b47a42;background:#d4ab5a0a;border-radius:10px;padding:16px;margin:16px 0}.manual-files h4{margin:0;color:#f0d8b2;font-size:.86rem}.manual-files p{font-size:.74rem;color:#adb5cb;line-height:1.6}.manual-files>div{display:flex;gap:12px;justify-content:space-between;align-items:center;border-bottom:1px solid #c8bd951c;padding:10px 0;font-size:.73rem}.manual-files>div span{overflow-wrap:anywhere;min-width:0}.manual-files small{display:block;margin-top:4px;color:#9caac2}.manual-files button{font-size:.7rem;flex-shrink:0}.manual-files>label{margin-top:14px}
  .pending-pack{font-size:.65rem;color:#f4c79c;border:1px solid #d4a06645;padding:4px 6px;border-radius:5px}

  .visual-content-note{display:flex;align-items:center;justify-content:space-between;gap:20px;border:1px solid var(--stroke);background:linear-gradient(110deg,rgba(var(--primary-rgb),.12),#12213355);padding:18px 20px;border-radius:14px;margin-top:18px}.visual-content-note>div{display:flex;align-items:center;gap:14px}.visual-content-note strong{display:block;font-size:.86rem}.visual-content-note small{display:block;color:var(--muted);font-size:.74rem;line-height:1.6;margin-top:6px}.visual-content-note button{flex-shrink:0;font-size:.72rem}.filter-grid.visual-filters{grid-template-columns:1fr 1fr 1.55fr}.project-cover{position:relative;aspect-ratio:16/9;margin:-20px -20px 17px;overflow:hidden;background:linear-gradient(135deg,#254e53,#24223c);display:grid;place-items:center;isolation:isolate}.project-cover img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .25s}.project-cover:after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 45%,#090d2299);pointer-events:none}.project-cover>span{position:absolute;bottom:12px;left:16px;z-index:1;font-size:.56rem;letter-spacing:.14em;color:#fff;font-weight:700;background:#0c102599;border:1px solid #ffffff25;border-radius:4px;padding:5px 8px}.visual-card:hover .project-cover img{transform:scale(1.04)}.visual-card .project-top{margin-bottom:12px}.visual-card .project-top img{width:38px;height:38px;border-radius:9px}@media(max-width:700px){.visual-content-note{align-items:stretch;flex-direction:column}.filter-grid.visual-filters{grid-template-columns:1fr}.detail-header{flex-wrap:wrap}}
